-- Modify "events" table
ALTER TABLE "events" ADD CONSTRAINT "chk_events_age_category" CHECK (age_category = ANY (ARRAY['y8'::text, 'y10'::text, 'y12'::text, 'y14'::text, 'cadet'::text, 'junior'::text, 'senior'::text, 'veteran'::text, 'open'::text])), ADD CONSTRAINT "chk_events_gender" CHECK (gender = ANY (ARRAY['male'::text, 'female'::text, 'other'::text])), ADD CONSTRAINT "chk_events_rating_limit" CHECK (rating_limit = ANY (ARRAY['open'::text, 'b_and_under'::text, 'c_and_under'::text, 'd_and_under'::text, 'e_and_under'::text, 'unrated'::text])), ADD CONSTRAINT "chk_events_type" CHECK (type = ANY (ARRAY['individual'::text, 'team'::text])), ADD CONSTRAINT "chk_events_weapon" CHECK (weapon = ANY (ARRAY['foil'::text, 'epee'::text, 'sabre'::text])), ADD COLUMN "type" text NULL, ADD COLUMN "weapon" text NULL, ADD COLUMN "gender" text NULL, ADD COLUMN "age_category" text NULL, ADD COLUMN "rating_limit" text NULL, ADD COLUMN "qualifier" boolean NOT NULL DEFAULT false;
-- Modify "tournaments" table
ALTER TABLE "tournaments" ADD CONSTRAINT "chk_tournaments_sanctioning_authority" CHECK (sanctioning_authority = ANY (ARRAY['askfred'::text, 'usa_fencing'::text, 'fie'::text, 'other'::text])), ADD COLUMN "venue" text NULL, ADD COLUMN "sanctioning_authority" text NULL;
